#include "gpu_batched_matvec.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{float maximum=0;for(int rows:{129,512,16384}){int cols=513,slots=4;Vec w(size_t(rows)*cols),x(slots*cols);for(size_t i=0;i<w.size();++i)w[i]=float(int(i%23)-11)*.01f;for(size_t i=0;i<x.size();++i)x[i]=float(int(i%17)-8)*.03f;Device a(w),b(x),ref(rows*slots),out(rows*slots);for(int k=0;k<slots;++k)ds_matvec_warp<<<(rows+3)/4,128>>>(a.p,b.p+k*cols,ref.p+k*rows,rows,cols);ds_batched_matvec<<<dim3((rows+3)/4,slots),128>>>(a.p,b.p,out.p,rows,cols,slots);check(cudaGetLastError());auto r=ref.host(),o=out.host();for(size_t i=0;i<r.size();++i){if(!std::isfinite(o[i]))return 2;maximum=std::max(maximum,std::abs(r[i]-o[i]));}if(r!=o)return 1;}printf("PASS batched4 vs serial4 bitwise identical across3shapes including tails max=%.9g\n",maximum);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 3;}}
